#define LED_BLUE   25   // Пин синего светодиода
#define LED_RED    26   // Пин красного светодиода

const int FLASH_ON   = 80;   // Длительность вспышки, мс
const int FLASH_OFF  = 80;   // Пауза между вспышками в серии, мс
const int SERIES_END = 300;  // Пауза после серии, мс

void setup() {
  pinMode(LED_BLUE, OUTPUT);
  pinMode(LED_RED, OUTPUT);
}

// Функция: серия из двух вспышек
void doubleFlash(int pin) {
  digitalWrite(pin, HIGH);
  delay(FLASH_ON);
  digitalWrite(pin, LOW);
  delay(FLASH_OFF);

  digitalWrite(pin, HIGH);
  delay(FLASH_ON);
  digitalWrite(pin, LOW);
  delay(SERIES_END);
}

void loop() {
  doubleFlash(LED_BLUE);   // Серия синего
  doubleFlash(LED_RED);    // Серия красного
}
